{
  "section_id": "artifacts",
  "section": {
    "upload_batch": {
      "prepare_tool": "flywheel_prepare_artifact_uploads",
      "finalize_tool": "flywheel_finalize_artifact_uploads",
      "execution_linkage": {
        "execution_id": "optional",
        "notes": "Set execution_id when the artifact is execution-derived. Execution linkage is not globally required for all artifact types."
      },
      "raw_file_upload_required": true,
      "upload_step": {
        "method": "PUT",
        "target": "prepare.items[].upload_url",
        "required_headers_field": "prepare.items[].upload_headers",
        "body": "raw_file_bytes"
      },
      "prepare_request_items_contract": {
        "type": "object_array",
        "required_fields": [
          "artifact_type",
          "filename",
          "media_type"
        ],
        "optional_fields": [
          "title",
          "execution_id",
          "metadata",
          "note"
        ],
        "notes": "prepare.items[] is structured object input. The transport layer may tolerate stringified JSON as a compatibility measure; this tolerance is not contractual and may be removed."
      },
      "upload_body": "raw_file_bytes",
      "forbidden_upload_payload_kinds": [
        "json_metadata_wrapper"
      ],
      "stage_upload_http_status_code": 202,
      "stage_upload_semantics": "accepted_and_staged",
      "single_revision_bump_on_finalize": true,
      "optional_note_field": {
        "field": "note",
        "default": "",
        "applies_to": "artifact_metadata_record",
        "markdown_allowed": true
      },
      "supported_artifact_types": [
        "text",
        "table",
        "json",
        "image",
        "banner",
        "html",
        "plotly_html",
        "vega",
        "checkpoint",
        "binary",
        "diff_carousel"
      ]
    },
    "artifact_metadata_contract": {
      "title": {
        "required_non_empty": true,
        "display_label_field": "title",
        "normalization_priority": [
          "explicit_title",
          "payload.title",
          "payload.name",
          "basename(payload.path|payload.filename|payload.file)",
          "basename(filename)",
          "basename(storage_path)",
          "artifact_type",
          "artifact"
        ],
        "must_not_derive_from": [
          "storage_url"
        ]
      },
      "storage_url": {
        "purpose": "raw_artifact_byte_read_url",
        "must_not_be_used_as_display_label": true
      }
    },
    "guidance": {
      "empirical_artifacts": "use flywheel_prepare_artifact_uploads, raw-file upload, and flywheel_finalize_artifact_uploads to publish experiment evidence before empirical completed commits"
    },
    "durable_contract_rules": [
      "For empirical work, publish evidence with `flywheel_prepare_artifact_uploads`, upload raw file bytes, then `flywheel_finalize_artifact_uploads` before commit.",
      "Artifact metadata records expose a non-empty `title` suitable for display labels; title normalization must never derive from `storage_url`."
    ]
  }
}

